import{_ as a,y as i,a as g,o as l,a2 as t,D as n,g as s,I as r}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Design","description":"","frontmatter":{},"headers":[],"relativePath":"configure/design.md","filePath":"configure/design.md","lastUpdated":1789441803000}'),d={name:"configure/design.md"};function h(c,e,u,p,m,f){const o=i("ImagePopup");return l(),g("div",null,[e[0]||(e[0]=t('<h1 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h1><p>The <strong>Design</strong> screen holds the logo and favicon of the admin panel, and how the storefront header shows your categories. Both sections apply to the whole store.</p><h2 id="admin-logo" tabindex="-1">Admin logo <a class="header-anchor" href="#admin-logo" aria-label="Permalink to &quot;Admin logo&quot;">​</a></h2><p>The <strong>Logo Image</strong> replaces the Bagisto logo in the admin panel header, on the admin sign-in and password pages, and in the emails sent to the admin and to inventory sources. The <strong>Favicon</strong> is the small icon browsers show in the admin panel&#39;s tab.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Design</strong>.</li><li>In <strong>Admin Logo</strong>, under <strong>Logo Image</strong>, click <strong>Add Image</strong>.</li><li>Choose your logo file.</li><li>Under <strong>Favicon</strong>, click <strong>Add Image</strong>.</li><li>Choose the icon file.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(o,{src:"/images/configure/design-settings.png",alt:"Design screen with the Admin Logo and Menu Category View sections"}),e[1]||(e[1]=t('<p>The file types each field accepts are listed under its <strong>Add Image</strong> button: BMP, JPEG, JPG, PNG, WEBP or SVG for the logo, and ICO as well for the favicon. To change or remove an image later, point to it and use its <strong>Replace</strong> or <strong>Delete</strong> icon; the change applies when you save. The storefront&#39;s own logo and favicon are set per channel under <a href="./../settings/channels.html">Channels</a>.</p><h2 id="menu-category-view" tabindex="-1">Menu category view <a class="header-anchor" href="#menu-category-view" aria-label="Permalink to &quot;Menu category view&quot;">​</a></h2><p><strong>Menu Category View</strong> decides how the storefront header shows your categories on desktop screens:</p><ul><li><strong>Default Menu</strong> lists every top-level category across the header. Pointing at a category opens a panel with its subcategories.</li><li><strong>Sidebar Menu</strong> adds an <strong>All</strong> button that opens a <strong>Categories</strong> side panel with every category and its subcategories, and lists only the first four top-level categories across the header. It suits a store with many categories.</li></ul><p>If the setting has never been saved, <strong>Default Menu</strong> is used, but a new installation is set to <strong>Sidebar Menu</strong>. The mobile header keeps its own menu whichever you choose.</p><ol><li>Go to <strong>Configure &gt;&gt; General &gt;&gt; Design</strong>.</li><li>In <strong>Menu Category View</strong>, choose <strong>Default Menu</strong> or <strong>Sidebar Menu</strong>.</li><li>To see what a style looks like, click <strong>Preview Default Menu</strong> or <strong>Preview Sidebar Menu</strong> below the field.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),n(o,{src:"/images/configure/design-menu-preview.png",alt:"Sidebar Menu preview with the Categories side panel open over the storefront"}),e[2]||(e[2]=s("p",null,[r("Which categories the menu lists, and in what order, is set by each channel's root category and the categories' positions. See "),s("a",{href:"./../category/create-category.html#root-categories-and-the-storefront-menu"},"Categories"),r(".")],-1))])}const v=a(d,[["render",h]]);export{_ as __pageData,v as default};
